// docs/CONFORMANCE.md, generated by the G-wpt-subset gate (never edited by hand).
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { resolve } from 'node:path';
import { PROJECT_ROOT } from '../harness/lib/util.mjs';

const OUT = resolve(PROJECT_ROOT, 'docs/CONFORMANCE.md');
const NOTES_MARK = '<!-- PROGRESS NOTES (hand-written, kept by the generator) -->';
const f = x => (x.status === 'MISSING' ? '-' : `${x.np}/${x.n}`);

function bundleHash() {
  const file = resolve(PROJECT_ROOT, 'dist/hic-live-polyfill.iife.js');
  return existsSync(file) ? createHash('sha256').update(readFileSync(file)).digest('hex').slice(0, 16) : 'n/a';
}

function summaryTable(result, docs) {
  const { files, subtests } = result.counts;
  return [
    '| | oracle A (native) | subject B (polyfill) | control C (no polyfill) |', '|---|---|---|---|',
    `| files fully passing | ${files.A} / ${files.total} | ${files.B} / ${files.total} | ${files.C} / ${files.total} |`,
    `| subtests passing | ${subtests.A} / ${subtests.total} | ${subtests.B} / ${subtests.total} | ${subtests.C} / ${subtests.total} |`,
    `| browser | ${docs.A.config.version}, \`--enable-blink-features=CanvasDrawElement\` | ${docs.B.config.version}, \`dist/hic-live-polyfill.iife.js\` | ${docs.C.config.version} |`,
  ].join('\n');
}

function driftSection(result) {
  const d = result.drift;
  if (!d) return '';
  const { files, subtests } = result.counts;
  const byFile = new Map();
  for (const x of d.subtests) byFile.set(x.id, (byFile.get(x.id) ?? 0) + 1);
  return `
**Oracle drift.** The oracle ran on ${d.oracle}, but the pinned WPT revision is the copy that ${d.build} imported (\`test/vendor/wpt/VERSION.json\`). Canary auto-updates and the newer build implements post-pin API changes
(rendering and API changes after the pinned revision), so ${d.subtests.length} subtests that the pinned build passed fail in this oracle run. They are triaged as native passes from
\`test/wpt/oracle-baseline.json\` (every full run of ${d.build}), so a polyfill failure there still needs a written reason. Oracle at the pinned build: **${files.P} / ${files.total} files, ${subtests.P} / ${subtests.total} subtests**.
Affected files: ${[...byFile].map(([id, n]) => `\`${id}\` (${n})`).join(', ')}.
`;
}

function categoryTable(result) {
  const names = { 'pass-both': 'passes in oracle and subject', 'native-issue': 'NATIVE/TEST ISSUE (the oracle fails it too, or the test needs the real top layer / fullscreen)', 'subject-only': 'subject passes, oracle fails',
    bug: 'polyfill BUG (open)', deviation: 'documented DEVIATION', impossible: 'IMPOSSIBLE for a userland polyfill', flaky: 'FLAKY (subject result changes between repetitions)', unexplained: 'UNEXPLAINED (gate fails)' };
  const rows = Object.keys(names).map(k => `| ${names[k]} | ${result.cat[k]} | ${result.catFiles[k] ?? 0} |`);
  return ['| category | subtests | files (worst subtest) |', '|---|---|---|', ...rows].join('\n');
}

function nativePassesWeFail(result) {
  const lines = [];
  for (const r of result.rows) for (const s of r.subs) lines.push(`- \`${r.id}\` :: ${s.name.slice(0, 110)} -> ${s.category}${s.reason ? ` (${s.reason})` : ''}`);
  return lines.length ? lines.join('\n') : '(none)';
}

function perTest(result) {
  const lines = ['| test | oracle | subject | control | category | reason |', '|---|---|---|---|---|---|'];
  for (const r of result.rows) {
    lines.push(`| \`${r.id}\` | ${f(r.A)} | ${f(r.B)}${r.B.stable === false ? ' (unstable)' : ''} | ${f(r.C)} | ${r.category} | ${(r.reason ?? '').replace(/\|/g, '/')} |`);
  }
  return lines.join('\n');
}

/** The open polyfill bugs (category `bug`, reason `WPT-Bn`) of expectations.json with their notes, one line per bug id. */
function openBugs(expectations) {
  const byId = new Map();
  for (const [id, e] of Object.entries(expectations.tests ?? {})) {
    for (const x of [e, ...Object.values(e.subtests ?? {})]) {
      if (x.category !== 'bug') continue;
      if (!byId.has(x.reason)) byId.set(x.reason, { note: x.note ?? '', tests: [] });
      byId.get(x.reason).tests.push(id);
    }
  }
  return byId.size ? [...byId].sort((a, b) => Number(a[0].slice(5)) - Number(b[0].slice(5))).map(([bug, b]) => `- **${bug}** (${b.tests.map(t => `\`${t}\``).join(', ')}): ${b.note}`).join('\n') : '(none)';
}

/** @returns {string} the written path */
export function writeConformance({ docs, result, expectations, failures }) {
  const version = JSON.parse(readFileSync(resolve(PROJECT_ROOT, 'test/vendor/wpt/VERSION.json'), 'utf8'));
  const date = (docs.B.finishedAt ?? new Date().toISOString()).slice(0, 10);
  const vacuous = Object.entries(expectations.controlPass ?? {}).map(([id, why]) => `- \`${id}\`: ${why}`).join('\n') || '(none)';
  const md = `# Conformance: the official WPT HTML-in-Canvas tests

Generated by \`npm run test:wpt\` (\`test/wpt/gate.mjs\`) on ${date}; do not edit by hand. Raw results: \`.scratch/results/wpt-{A,B,C}-latest.json\`. Triage reasons: \`test/wpt/expectations.json\`.

## What was run

- Tests: ${result.counts.files.total} files from web-platform-tests at commit \`${version.sha}\` (${version.commit}). They are the tests of
  \`html/canvas/element/manual/draw-element-image/**\` and \`html/canvas/offscreen/manual/draw-element-image/**\` (the HTML-in-Canvas tests; the directory is called \`manual\` but they are ordinary
  testharness, reftest and crash tests, all \`.tentative\`). Vendored under \`test/vendor/wpt\` (BSD-3-Clause, test time only, never shipped).
- Revision: the newest WPT commit that touches these tests. Chromium writes them, and the oracle is the Chromium build whose imported copy is closest:
  ${version.chromium.tag} (${version.chromium.match}). ${version.chromium.note.replace(/\. 158\.0\.8116\.0 and later.*$/, '.')} This is the \`content=drawable\` / \`drawable\` API (no \`layoutsubtree\`), with \`getElementImageDefaultSize\` and the one-argument \`getElementTransform\`.
- Runner: \`test/wpt/\` (zero dependencies), headed Chrome over CDP, one tab, viewport 800x600 at DPR 1, \`--hide-scrollbars\` (except the tests that style \`::-webkit-scrollbar\`, which run in a browser with the platform scrollbars shown), sRGB, https on \`web-platform.test\` / \`not-web-platform.test\` (self-signed, host rules to loopback).
  testharness: per-subtest results through \`testharnessreport.js\`; reftest: screenshot of test and reference, pixel comparison with the test's own \`<meta name=fuzzy>\`; crash tests: load, settle, no renderer crash.
  Every test runs ${docs.B.reps} times per configuration (control: once); a result that changes between repetitions is flagged unstable.
- Configurations: **A oracle** ${docs.A.config.version} with \`--enable-blink-features=CanvasDrawElement\` (native \`content=drawable\`); **B subject** ${docs.B.config.version} (no native feature) + \`dist/hic-live-polyfill.iife.js\` (sha256 ${bundleHash()}) injected in every document and cross-site frame, and \`dist/hic-live-worker.iife.js\` in every dedicated worker; **C control** ${docs.C.config.version} without the polyfill.
  Chrome stable with the flag only knows the pre-2026-09 names (\`layoutSubtree\`), so it cannot run these tests: it is not a configuration.

${summaryTable(result, docs)}
${driftSection(result)}
## Triage of every subtest

${categoryTable(result)}

Gate (\`G-wpt-subset\`) fails when (i) a subtest that passes natively and fails in the subject has no entry with a written reason in \`test/wpt/expectations.json\`, (ii) a control test passes without being a documented vacuous pass,
(iii) a test listed as expected-pass (or a partial-pass floor) regresses. Last run: ${failures.length ? `FAILED (${failures.length}): ${failures.slice(0, 5).join('; ').replace(/\|/g, '\\|')}` : 'OK'}.

### Control tests that pass without the polyfill (vacuous by construction)

${vacuous}

### Open polyfill bugs

${openBugs(expectations)}

### Native passes, polyfill fails (subtest level)

${nativePassesWeFail(result)}

## Per-test table

${perTest(result)}

## Not covered

- Everything outside \`draw-element-image\`: the 2D canvas tests of \`html/canvas/element\` and \`offscreen\` do not exercise this API.
- WPT changes that Chromium has made and not yet exported (the open export pull requests named in \`test/vendor/wpt/VERSION.json\`): they add assertions to three files and add new files; the oracle build already implements the behaviour behind the first ones.
- Chrome 154 native (legacy names), Firefox, Safari: not run. Display P3 canvases, a high-DPR display, video frames of an \`ElementImage\` in a worker and the real top layer are outside what a userland polyfill can observe.
`;
  // hand-written progress notes survive regeneration
  const old = existsSync(OUT) ? readFileSync(OUT, 'utf8') : '';
  const at = old.indexOf(NOTES_MARK);
  writeFileSync(OUT, at >= 0 ? md + '\n' + old.slice(at) : md);
  return OUT;
}
